@ zx_payload.S -- the EL1 payload the stage-2 probe runs.
@
@ WHAT THIS IS
@
@   A few dozen instructions that run at EL1 under stage 2, with no library,
@   no stack use worth the name and no console.  It is not a guest: a real
@   ThreadX guest comes later.  It is the smallest thing that can prove
@   stage 2 grants what it should and denies what it should not.
@
@ WHY IT DOES NOT PRINT
@
@   Deliberate.  A payload that printed would need an MMIO region of its own
@   at stage 2, which would add a variable to every result and would differ
@   between the model (semihosting, no peripheral) and the board (LINFlexD).
@   Instead it records progress bits in its own data region, and EL2 -- which
@   can always reach a partition's memory, because no AP encoding at EL2 can
@   deny it (docs/decisions.md D3) -- reads them out and reports.
@
@ WHY POINT 4 BELOW IS NOT OPTIONAL
@
@   zx_payload_violation sets ATTEMPTED before the access and SURVIVED after
@   it, then yields.  If stage 2 works, SURVIVED is never written and control
@   never reaches the yield: EL2 takes the fault instead.  If stage 2 does
@   NOT work, the payload comes back and says so.
@
@   That is the difference between a regression that can report "the payload
@   survived its violation -- it is not protected" and one that can only
@   report "no fault was captured".  The second cannot tell a working
@   protection failure from a broken test, which is exactly the trap the
@   Cortex-R52 Modules port work fell into once.
@
@ SECTIONS
@
@   .zx_payload_text and .zx_payload_data are placed by the linker script on
@   64-byte boundaries and sized to whole granules, because those are the two
@   stage-2 regions the probe programs.  Anything that leaked out of them
@   would be either unreachable or -- worse -- reachable through a region it
@   was not meant to be in.

#include "zx_port.h"
#include "zx_guest_abi.h"

    .syntax unified
    .arm

/* Progress bits in zx_payload_result.  Mirrored in zx_probe_main.c, which
   is the only reader; the two lists are checked against each other by eye
   because there is no shared header an assembler and a compiler could both
   take them from without inventing one for six constants.  The names are
   spelled identically in both files so a grep finds the pair.  */

    .equ    ZX_PAYLOAD_RAN,          (1 << 0)
    .equ    ZX_PAYLOAD_OWN_DATA_OK,  (1 << 1)
    .equ    ZX_PAYLOAD_HVC_RETURNED, (1 << 2)
    .equ    ZX_PAYLOAD_PROBE_OK,     (1 << 3)
    .equ    ZX_PAYLOAD_ATTEMPTED,    (1 << 4)
    .equ    ZX_PAYLOAD_SURVIVED,     (1 << 5)

    .equ    ZX_PAYLOAD_SENTINEL,     0xA5A5A5A5

    .section .zx_payload_text, "ax"
    .balign 64

/**************************************************************************/
/*  The payload's own EL1 vector table.                                   */
/*                                                                        */
/*  Inside the payload's code region on purpose.  EL2 installs it in VBAR  */
/*  before the first ERET, so an exception taken at EL1 rather than routed */
/*  to EL2 -- an alignment fault, an undefined instruction -- lands        */
/*  somewhere that can report itself instead of somewhere random.  Placing */
/*  it in EL2's own code region would have cost either a region or a       */
/*  prefetch abort at a confusing address.                                 */
/*                                                                        */
/*  Each entry issues a distinct HVC immediate, 0x10 + the vector index,   */
/*  which reaches EL2 as an unexpected trap carrying the vector number.    */
/*  A hang would say nothing; this says which vector.                      */
/**************************************************************************/

    .balign 32
    .global zx_payload_vectors
zx_payload_vectors:
    hvc     #0x10                           /* 0x00  reset                 */
    hvc     #0x11                           /* 0x04  undefined instruction */
    hvc     #0x12                           /* 0x08  SVC                   */
    hvc     #0x13                           /* 0x0C  prefetch abort        */
    hvc     #0x14                           /* 0x10  data abort            */
    hvc     #0x15                           /* 0x14  reserved              */
    hvc     #0x16                           /* 0x18  IRQ                   */
    hvc     #0x17                           /* 0x1C  FIQ                   */

/**************************************************************************/
/*  ZX_PAYLOAD_ENTER -- the two instructions every entry point starts with.*/
/*                                                                        */
/*  A stack is set even though nothing here pushes anything.  SP_svc is    */
/*  UNKNOWN out of an ERET, and an unset SP that is never used is one      */
/*  edit away from an unset SP that is.                                   */
/**************************************************************************/

    .macro  ZX_PAYLOAD_ENTER
    ldr     sp, =__zx_payload_stack_top
    ldr     r2, =zx_payload_result
    ldr     r3, [r2]
    orr     r3, r3, #ZX_PAYLOAD_RAN
    str     r3, [r2]
    .endm

/**************************************************************************/
/*  zx_payload_grant_check -- does stage 2 GRANT what it should?           */
/*                                                                        */
/*  Writes a sentinel into its own data region and reads it back.  Both    */
/*  halves matter: a write that silently went nowhere and a read that      */
/*  returned a stale value are different failures, and only the comparison */
/*  distinguishes them from success.                                       */
/**************************************************************************/

    .global zx_payload_grant_check
    .type   zx_payload_grant_check, %function
zx_payload_grant_check:
    ZX_PAYLOAD_ENTER

    ldr     r0, =zx_payload_scratch
    ldr     r1, =ZX_PAYLOAD_SENTINEL
    str     r1, [r0]
    dsb
    ldr     r0, [r0]
    cmp     r0, r1
    bne     zx_payload_grant_done

    ldr     r3, [r2]
    orr     r3, r3, #ZX_PAYLOAD_OWN_DATA_OK
    str     r3, [r2]

zx_payload_grant_done:
    dsb
    hvc     #ZX_ASM_HVC_IMM_YIELD
    .size   zx_payload_grant_check, . - zx_payload_grant_check

/**************************************************************************/
/*  zx_payload_hvc_check -- is the Phase-0 hypercall vector live?          */
/*                                                                        */
/*  HVC #0 is the empty vector: EL2 counts it and returns here.  Reaching  */
/*  the instruction after it is the proof, and it is proof of something    */
/*  the fault paths cannot show -- that EL2 can be entered and LEFT again  */
/*  without the guest's state being disturbed.                            */
/**************************************************************************/

    .global zx_payload_hvc_check
    .type   zx_payload_hvc_check, %function
zx_payload_hvc_check:
    ZX_PAYLOAD_ENTER

    hvc     #ZX_ASM_HVC_IMM_NOP

    ldr     r2, =zx_payload_result
    ldr     r3, [r2]
    orr     r3, r3, #ZX_PAYLOAD_HVC_RETURNED
    str     r3, [r2]
    dsb
    hvc     #ZX_ASM_HVC_IMM_YIELD
    .size   zx_payload_hvc_check, . - zx_payload_hvc_check

/**************************************************************************/
/*  zx_payload_probe_read -- read the address in r0.                       */
/*                                                                        */
/*  Used twice against the SAME address, once with the covering region     */
/*  enabled and once with it disabled, which is how the HPRENR width       */
/*  question is answered FUNCTIONALLY rather than by reading a register    */
/*  back.  A register that accepts a bit above 15 and ignores it would     */
/*  pass a read-back test and fail this one, and that is the outcome worth */
/*  catching: it would make a one-write partition switch silently wrong.   */
/*                                                                        */
/*  PROBE_OK is cleared on entry so that the second run cannot inherit the */
/*  first run's success.                                                   */
/**************************************************************************/

    .global zx_payload_probe_read
    .type   zx_payload_probe_read, %function
zx_payload_probe_read:
    ZX_PAYLOAD_ENTER

    ldr     r3, [r2]
    bic     r3, r3, #(ZX_PAYLOAD_PROBE_OK)
    str     r3, [r2]
    dsb

    ldr     r1, [r0]                        @ may take a stage-2 fault

    ldr     r0, =zx_payload_probe_value
    str     r1, [r0]

    ldr     r3, [r2]
    orr     r3, r3, #ZX_PAYLOAD_PROBE_OK
    str     r3, [r2]
    dsb
    hvc     #ZX_ASM_HVC_IMM_YIELD
    .size   zx_payload_probe_read, . - zx_payload_probe_read

/**************************************************************************/
/*  zx_payload_violation -- write to the address in r0, which must fault.  */
/*                                                                        */
/*  ATTEMPTED is set and flushed BEFORE the access, so that a run which    */
/*  faults can still prove the payload got as far as trying.  SURVIVED is  */
/*  set after it, and must never be observed set.  See the file header.    */
/**************************************************************************/

    .global zx_payload_violation
    .type   zx_payload_violation, %function
zx_payload_violation:
    ZX_PAYLOAD_ENTER

    ldr     r3, [r2]
    orr     r3, r3, #ZX_PAYLOAD_ATTEMPTED
    str     r3, [r2]
    dsb

    ldr     r1, =ZX_PAYLOAD_SENTINEL
    str     r1, [r0]                        @ must take a stage-2 fault

    ldr     r3, [r2]
    orr     r3, r3, #ZX_PAYLOAD_SURVIVED
    str     r3, [r2]
    dsb
    hvc     #ZX_ASM_HVC_IMM_YIELD
    .size   zx_payload_violation, . - zx_payload_violation

    .balign 64

/**************************************************************************/
/*  The payload's data region.                                            */
/*                                                                        */
/*  Loaded rather than NOLOAD, with explicit initialisers, so that nothing */
/*  has to zero it: the reset path zeroes ZoneX's .bss, and a payload area */
/*  that depended on that would depend on the payload living inside the    */
/*  hypervisor's own bss -- which is exactly what stage 2 must keep it out */
/*  of.                                                                    */
/**************************************************************************/

    .section .zx_payload_data, "aw"
    .balign 64

    .global zx_payload_result
    .type   zx_payload_result, %object
zx_payload_result:
    .word   0
    .size   zx_payload_result, . - zx_payload_result

    .global zx_payload_scratch
    .type   zx_payload_scratch, %object
zx_payload_scratch:
    .word   0
    .size   zx_payload_scratch, . - zx_payload_scratch

    .global zx_payload_probe_value
    .type   zx_payload_probe_value, %object
zx_payload_probe_value:
    .word   0
    .size   zx_payload_probe_value, . - zx_payload_probe_value

    .balign 8
    .space  256
    .global __zx_payload_stack_top
__zx_payload_stack_top:

/**************************************************************************/
/*  The granule region 16 covers.                                         */
/*                                                                        */
/*  Its own section, so that the linker script can put it on a granule     */
/*  boundary well away from anything else: a region that overlapped        */
/*  another enabled region would be CONSTRAINED UNPREDICTABLE, and on the  */
/*  S32Z280 it aborts.  The sentinel is what makes the read a real check   */
/*  rather than a liveness test -- a read that succeeded against the wrong */
/*  memory would otherwise look identical to one that succeeded.          */
/**************************************************************************/

    .section .zx_high_probe, "aw"
    .balign 64
    .global zx_high_probe_word
    .type   zx_high_probe_word, %object
zx_high_probe_word:
    .word   0x5A5AC0DE
    .size   zx_high_probe_word, . - zx_high_probe_word

/**************************************************************************/
/*                                                                        */
/*  THE RELOCATABLE GUEST BLOB                                            */
/*                                                                        */
/*  Everything above runs in ONE place, at the address it was linked for.  */
/*  This does not: it is assembled once, kept in the hypervisor's own      */
/*  memory, and COPIED into each partition's code window, so that two      */
/*  partitions can run the same program in different memory.  Without      */
/*  that, "set A denies B and set B denies A" has only one half that can   */
/*  be demonstrated -- the other partition would have no code to run.     */
/*                                                                        */
/*  WHAT MAKES IT SURVIVE THE COPY                                        */
/*                                                                        */
/*  Not PC-relative arithmetic.  The hypervisor passes the partition's     */
/*  DATA WINDOW BASE in r0 and every data access is an offset from it, so  */
/*  there is nothing to relocate.  Three things could have broken and do   */
/*  not:                                                                   */
/*                                                                        */
/*    branches            already PC-relative; survive untouched          */
/*    a literal CONSTANT  loaded PC-relatively from a nearby pool, and     */
/*                        the pool is copied with the code                 */
/*    a literal ADDRESS   would NOT survive -- and there is not one.  That */
/*                        is the whole discipline of this section: no      */
/*                        "ldr rN, =symbol" anywhere below.                */
/*                                                                        */
/*  There is also no stack.  SP_svc is UNKNOWN out of an ERET and every    */
/*  entry point below is straight-line code that ends in an HVC, so a      */
/*  stack pointer would be a thing to get wrong for no benefit.  The       */
/*  moment anything here pushes, it needs the window to hold a stack and   */
/*  this comment needs deleting.                                          */
/*                                                                        */
/*  ENTRY POINTS SIT AT DECLARED OFFSETS.  The hypervisor computes them as */
/*  window_base + constant, so a routine that outgrew its slot would        */
/*  silently become the wrong entry point.  Each slot is padded to its      */
/*  declared offset and the assembler ERRORS if the previous routine has    */
/*  already passed it, which turns that into a build failure.               */
/**************************************************************************/

    .section .zx_guest_blob, "ax", %progbits
    .balign 64
    .global zx_guest_blob_start
zx_guest_blob_start:

/* Pad to a declared entry offset.
 *
 * .org and not a computed .space, and that is not a style choice: .org
 * takes an offset from the START OF THE SECTION, which is exactly what a
 * blob offset is, and it REFUSES to move backwards -- so a routine that
 * outgrew its slot fails the assembly instead of quietly displacing the
 * next entry point.  Both properties for free.
 *
 * The obvious alternative, guarding a .space with
 * ".if (. - zx_guest_blob_start) > offset", assembles under GNU as and is
 * rejected by LLVM's assembler, which will not treat the difference of two
 * labels as an absolute expression before layout.  ZoneX builds with both.
 */
    .macro  ZX_GUEST_SLOT offset, name
    .org    \offset
    .endm

/**************************************************************************/
/*  The guest's own EL1 vector table, at offset 0 of the blob.             */
/*                                                                        */
/*  At offset 0 so that VBAR is simply the partition's code-window base --  */
/*  one fewer computed address in the hypervisor, and one fewer thing to    */
/*  get wrong per partition.  Each entry issues a distinct HVC immediate    */
/*  so that an exception taken AT EL1, rather than routed to EL2, arrives   */
/*  at EL2 saying which vector it came from instead of hanging.            */
/**************************************************************************/

    ZX_GUEST_SLOT ZX_GUEST_OFF_VECTORS, vectors
zx_guest_vectors:
    hvc     #0x20                           @ 0x00  reset
    hvc     #0x21                           @ 0x04  undefined instruction
    hvc     #0x22                           @ 0x08  SVC
    hvc     #0x23                           @ 0x0C  prefetch abort
    hvc     #0x24                           @ 0x10  data abort
    hvc     #0x25                           @ 0x14  reserved
    hvc     #0x26                           @ 0x18  IRQ
    hvc     #0x27                           @ 0x1C  FIQ

/**************************************************************************/
/*  grant -- can this partition reach its OWN data?                        */
/*                                                                        */
/*  The positive half of the isolation claim, and it has to come first: a   */
/*  run in which every access fails would satisfy every "must fault" check  */
/*  in this image and prove nothing at all.                                */
/*                                                                        */
/*  r0 = the partition's data window.  The sentinel is passed in rather     */
/*  than hard-coded, so that each partition writes a DIFFERENT one and EL2  */
/*  reading both back cannot mistake one partition's success for the        */
/*  other's.                                                               */
/**************************************************************************/

    ZX_GUEST_SLOT ZX_GUEST_OFF_GRANT, grant
    .global zx_guest_grant
    .type   zx_guest_grant, %function
zx_guest_grant:
    ldr     r3, [r0, #ZX_GD_PROGRESS]
    orr     r3, r3, #ZX_GP_ENTERED
    str     r3, [r0, #ZX_GD_PROGRESS]

    ldr     r1, [r0, #ZX_GD_PUBLISH_VALUE]  @ this partition's sentinel
    str     r1, [r0, #ZX_GD_SCRATCH]
    dsb
    ldr     r2, [r0, #ZX_GD_SCRATCH]
    cmp     r2, r1
    bne     1f

    ldr     r3, [r0, #ZX_GD_PROGRESS]
    orr     r3, r3, #ZX_GP_OWN_DATA_OK
    str     r3, [r0, #ZX_GD_PROGRESS]
1:
    dsb
    hvc     #ZX_ASM_HVC_IMM_YIELD
    .size   zx_guest_grant, . - zx_guest_grant

/**************************************************************************/
/*  probe -- read the address EL2 left in the mailbox.                     */
/*                                                                        */
/*  The load may take a stage-2 fault, and when it does this routine never */
/*  reaches its next instruction: the fault goes to EL2, which resumes the */
/*  hypervisor rather than the guest.  So SURVIVED being CLEAR afterwards  */
/*  is the evidence that the access was stopped.                           */
/*                                                                        */
/*  The bit is cleared on entry rather than assumed clear, because this    */
/*  entry point is called more than once per partition -- at the other      */
/*  partition's data, and at the ungranted granule next to its own -- and   */
/*  a second call inheriting the first call's success would report the      */
/*  opposite of the truth.                                                 */
/**************************************************************************/

    ZX_GUEST_SLOT ZX_GUEST_OFF_PROBE, probe
    .global zx_guest_probe
    .type   zx_guest_probe, %function
zx_guest_probe:
    ldr     r3, [r0, #ZX_GD_PROGRESS]
    orr     r3, r3, #ZX_GP_ENTERED
    bic     r3, r3, #ZX_GP_PROBE_SURVIVED
    str     r3, [r0, #ZX_GD_PROGRESS]
    dsb

    ldr     r1, [r0, #ZX_GD_TARGET]
    ldr     r2, [r1]                        @ may take a stage-2 fault

    str     r2, [r0, #ZX_GD_PROBED]
    ldr     r3, [r0, #ZX_GD_PROGRESS]
    orr     r3, r3, #ZX_GP_PROBE_SURVIVED
    str     r3, [r0, #ZX_GD_PROGRESS]
    dsb
    hvc     #ZX_ASM_HVC_IMM_YIELD
    .size   zx_guest_probe, . - zx_guest_probe

/**************************************************************************/
/*  publish -- write the heartbeat into the shared granule.                */
/*                                                                        */
/*  Only the publishing partition can do this.  A reader running the same  */
/*  entry point takes a stage-2 PERMISSION fault rather than a region       */
/*  miss -- DFSC 0x0C rather than 0x04 -- and telling those two apart is    */
/*  how the run shows that the shared granule is read-only to a reader      */
/*  rather than simply absent from its map.                                */
/**************************************************************************/

    ZX_GUEST_SLOT ZX_GUEST_OFF_PUBLISH, publish
    .global zx_guest_publish
    .type   zx_guest_publish, %function
zx_guest_publish:
    ldr     r3, [r0, #ZX_GD_PROGRESS]
    orr     r3, r3, #ZX_GP_ENTERED
    str     r3, [r0, #ZX_GD_PROGRESS]

    ldr     r1, [r0, #ZX_GD_SHARED]
    ldr     r2, [r0, #ZX_GD_PUBLISH_VALUE]
    str     r2, [r1]                        @ may take a permission fault
    dsb

    ldr     r3, [r0, #ZX_GD_PROGRESS]
    orr     r3, r3, #ZX_GP_PUBLISHED
    str     r3, [r0, #ZX_GD_PROGRESS]
    dsb
    hvc     #ZX_ASM_HVC_IMM_YIELD
    .size   zx_guest_publish, . - zx_guest_publish

/**************************************************************************/
/*  consume -- read the shared granule.                                    */
/*                                                                        */
/*  Every partition may.  What it read is reported through the mailbox so   */
/*  that EL2 can check the VALUE, not merely that the read completed: a     */
/*  read succeeding against the wrong granule looks identical to one        */
/*  succeeding against the right one.                                      */
/**************************************************************************/

    ZX_GUEST_SLOT ZX_GUEST_OFF_CONSUME, consume
    .global zx_guest_consume
    .type   zx_guest_consume, %function
zx_guest_consume:
    ldr     r3, [r0, #ZX_GD_PROGRESS]
    orr     r3, r3, #ZX_GP_ENTERED
    str     r3, [r0, #ZX_GD_PROGRESS]

    ldr     r1, [r0, #ZX_GD_SHARED]
    ldr     r2, [r1]                        @ may take a stage-2 fault

    str     r2, [r0, #ZX_GD_PROBED]
    ldr     r3, [r0, #ZX_GD_PROGRESS]
    orr     r3, r3, #ZX_GP_CONSUMED
    str     r3, [r0, #ZX_GD_PROGRESS]
    dsb
    hvc     #ZX_ASM_HVC_IMM_YIELD
    .size   zx_guest_consume, . - zx_guest_consume

/* The blob's declared size, checked rather than assumed: the hypervisor
   copies exactly this many bytes and the manifest declares an image of
   exactly this length, so a blob that outgrew it would be copied
   truncated -- which presents as a guest that runs partway.  */

    ZX_GUEST_SLOT ZX_GUEST_BLOB_SIZE, end
    .global zx_guest_blob_end
zx_guest_blob_end:
